  [message.sendblue_number, message.from_number, message.to_number].some((number) => number?.endsWith("0577"))
);
const counterpartCandidates = messages.filter((message) =>
  !message.is_outbound &&
  message.service === "iMessage" &&
  [message.from_number, message.number].some((number) => number?.endsWith("7386"))
);
const line = lineCandidates.flatMap((message) => [message.sendblue_number, message.from_number, message.to_number]).find((number) => number?.endsWith("0577"));
const counterpart = counterpartCandidates.flatMap((message) => [message.from_number, message.number]).find((number) => number?.endsWith("7386"));
