const bypassResult = await tools.vercel_api.user.personalvercelapi.projects.updateProjectProtectionBypass({
  idOrName: projectId,
  teamId,
  body: { generate: { note: "Sendblue Preview receive webhook automation bypass" } }
});
if (!bypassResult.ok) return { phase: "protection", service: "vercel-bypass", code: bypassResult.error.code, status: bypassResult.error.status ?? null };

const created = Array.isArray(configResult.data.created) ? configResult.data.created : [configResult.data.created];
