return {
  phase: "complete",
  env: {
    requested: config.map((entry) => entry.key),
    createdOrUpdated: created.map((entry) => ({ key: entry.key, target: entry.target, type: entry.type })),
    failedCount: failed.length
  },
  sendblue: {
    lineSuffix: line.slice(-4),
    counterpartSuffix: counterpart.slice(-4),
    service: "iMessage",
    messageSampleCount: messages.length
  },
  bypass: {
    status: bypassResult.http?.status ?? null,
    configured: Boolean(bypassResult.data.protectionBypass),
    secretNeedsOnePasswordStorage: true
  }
};`}); for (const c of r.content) if (c.type === "text") text(c.text);

